static const z_t6357_t _zag1641 = { { .data = "win_sep", .size = 7 }, { .length = 1, .data = _zag1640 }, { .length = 0, .data = NULL }, { .data = "static int z_win_sep(char c) {\n    return c == '\\\\' || c == '/';\n}", .size = 66 } };
